before:
Complete local Rust example; the app itself does not execute it:
```rust
use std::sync::mpsc;
use std::thread;

fn main() {
    let (sender, receiver) = mpsc::channel();
    let worker = thread::spawn(move || {
        sender.send(String::from("ready")).expect("receiver gone");
    });
    for message in receiver { println!("{message}"); }
    worker.join().expect("worker panicked");
}
```

